initial_condition:
with {
    the SUT being in the "initial state" and
    the SUT contains a Context Source Registration 
        with id equal to ${context_source_registration_id}
        and payload set to ${context_source_registration_payload_file_path}
}

test_cases.then:
then {
    the SUT sends a valid Response for the operations:
        Update Context Source Registration With Return with Response Status Code set to 204     and
        Retrieve Context Source Registration with Response Body containing the key '['endpoint']', with the value 'http://my.new.csource.org:1026'
}

test_cases.when:
when {
    the SUT receives a Request from the client containing:
        URL set to '/ngsi-ld/v1/csourceRegistrations/{registration_id}'
        method set to 'PATCH'
        Update Context Source Registration with id set to '${registration_id}' and registration update fragment set to '${registration_update_fragment}' and content-type set to 'application/json'
}
